def _A_cell(v, how=''):
    """A worked value with the calculation or the reason under it."""
    return f'<b class="gv">{v}</b>' + (f'<span class="gm">{how}</span>' if how else '')


def _A_tbl(head, rows, cls=''):
    """A table whose cells appear at chosen clicks. A cell is text (always shown) or (click, value, how)."""
    h = ''.join(f'<th>{TX(x)}</th>' for x in head)
    b = ''
    for r in rows:
        tds = ''
        for c in r:
            tds += f'<td>{ST(c[0], TX(_A_cell(c[1], c[2])))}</td>' if isinstance(c, tuple) else f'<td>{TX(c)}</td>'
        b += f'<tr>{tds}</tr>'
    return f'<table class="tbl2 {cls}"><tr>{h}</tr>{b}</table>'


def _A_li(items):
    return '<ul>' + ''.join(f'<li>{TX(x)}</li>' for x in items) + '</ul>'


